CREATE TABLE IF NOT EXISTS `khoa` (
    `ma` VARCHAR(30) NOT NULL,
    `stt` SMALLINT UNSIGNED DEFAULT NULL,
    `ten` VARCHAR(255) NOT NULL,
    `ghi_chu` TEXT DEFAULT NULL,
    `ma_khoa_goc` VARCHAR(30) DEFAULT NULL,
    `is_active` TINYINT(1) NOT NULL DEFAULT 1,
    `quyet_dinh` VARCHAR(50) NOT NULL DEFAULT '1804/QĐ-BYT',
    `ngay_hieu_luc` DATE NOT NULL DEFAULT '2026-06-19',
    `source_url` VARCHAR(500) NOT NULL,
    PRIMARY KEY (`ma`),
    KEY `idx_khoa_stt` (`stt`),
    KEY `idx_khoa_ten` (`ten`),
    KEY `idx_khoa_goc` (`ma_khoa_goc`),
    KEY `idx_khoa_active` (`is_active`),
    CONSTRAINT `fk_khoa_goc` FOREIGN KEY (`ma_khoa_goc`) REFERENCES `khoa` (`ma`)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ON DUPLICATE KEY UPDATE
    `stt` = VALUES(`stt`),
    `ten` = VALUES(`ten`),
    `ghi_chu` = VALUES(`ghi_chu`),
    `ma_khoa_goc` = VALUES(`ma_khoa_goc`),
    `is_active` = VALUES(`is_active`),
    `quyet_dinh` = VALUES(`quyet_dinh`),
    `ngay_hieu_luc` = VALUES(`ngay_hieu_luc`),
    `source_url` = VALUES(`source_url`);
